// UpdateATicketClassJSONBody defines parameters for UpdateATicketClass.
type UpdateATicketClassJSONBody struct {
	TicketClass *struct {
		// AutoHide Hide this ticket when it is not on sale
		AutoHide bool `json:"auto_hide"`

		// AutoHideAfter Override re-hide date for auto-hide
		AutoHideAfter string `json:"auto_hide_after"`

		// AutoHideBefore Override reveal date for auto-hide
		AutoHideBefore string `json:"auto_hide_before"`

		// Capacity Total available number of this ticket, required for non-donation and non-tiered ticket classes. For normal ticket, null or 0 is not allowed. For donation ticket, null or 0 means unlimited. For tiered inventory ticket, null or 0 means capacity is only limited by tier capacity and/or event capacity.
		Capacity *float32 `json:"capacity"`

		// Cost Cost of the ticket (currently currency must match event currency) e.g. $45 would be ‘USD,4500’
		Cost struct {
			// Currency The ISO 4217 3-character code of a currency
			Currency string `json:"currency"`

			// Display Provided for your convenience; its formatting may change depending on the locale you query the API with (for example, commas for decimal separators in European locales).
			Display string `json:"display"`

			// MajorValue You can get a value in the currency's major unit - for example, dollars or pound sterling - by taking the integer value provided and shifting the decimal point left by the exponent value for that currency as defined in ISO 4217
			MajorValue string `json:"major_value"`

			// Value The integer value of units of the minor unit of the currency (e.g. cents for US dollars)
			Value float32 `json:"value"`
		} `json:"cost"`

		// DeliveryMethods A list of the available delivery methods for this ticket class
		DeliveryMethods string `json:"delivery_methods"`

		// Description Description of the ticket
		Description string `json:"description"`

		// DisplayName Pretty long name of this ticket class. For tiered inventory tickets, this includes the tier name.
		DisplayName *string `json:"display_name,omitempty"`

		// Donation Is this a donation? (user-supplied cost)
		Donation bool `json:"donation"`

		// Free Is this a free ticket?
		Free bool `json:"free"`

		// HasPdfTicket Whether to include pdf ticket or not
		HasPdfTicket bool `json:"has_pdf_ticket"`

		// Hidden Hide this ticket
		Hidden bool `json:"hidden"`

		// HideDescription Hide the ticket description on the event page
		HideDescription bool `json:"hide_description"`

		// HideSaleDates Hide the sale dates on event landing and ticket selection page
		HideSaleDates *bool `json:"hide_sale_dates,omitempty"`

		// ImageId Image ID for this ticket class. Setting this to null will remove image from this ticket class.
		ImageId *string `json:"image_id"`

		// IncludeFee Absorb the fee into the displayed cost
		IncludeFee bool `json:"include_fee"`

		// InventoryTierId Optional ID of Inventory Tier with which to associate the ticket class
		InventoryTierId string `json:"inventory_tier_id"`

		// MaximumQuantity Maximum number per order (blank uses default value)
		MaximumQuantity float32 `json:"maximum_quantity"`

		// MinimumQuantity Minimum number per order
		MinimumQuantity float32 `json:"minimum_quantity"`

		// Name Name of this ticket type
		Name string `json:"name"`

		// OrderConfirmationMessage Order message per ticket type
		OrderConfirmationMessage *string `json:"order_confirmation_message"`

		// QuantitySold The number of sold tickets.
		QuantitySold *float32 `json:"quantity_sold,omitempty"`

		// QuantityTotal Deprecated, use `capacity` instead.
		QuantityTotal float32 `json:"quantity_total"`

		// ResourceUri Is an absolute URL to the API endpoint that will return you ticket class.
		ResourceUri *string `json:"resource_uri,omitempty"`

		// SalesChannels A list of all supported sales channels ([“online”], [“online”, “atd”], [“atd”])
		SalesChannels interface{} `json:"sales_channels"`

		// SalesEnd When the ticket stops being on sale (leave empty for ‘one hour before event start’)
		SalesEnd string `json:"sales_end"`

		// SalesEndRelative Relative values used to calculate ticket sales_end. Can only be used for series parent tickets.
		SalesEndRelative *struct {
			// Offset The amount of time in seconds that the ticket sales are offset before the event start or end. Nonnegative number.
			Offset float32 `json:"offset"`

			// RelativeToEvent Enum representing whether sales end relative to event start or end
			RelativeToEvent UpdateATicketClassJSONBodyTicketClassSalesEndRelativeRelativeToEvent `json:"relative_to_event"`
		} `json:"sales_end_relative"`

		// SalesStart When the ticket is available for sale (leave empty for ‘when event published’)
		SalesStart string `json:"sales_start"`

		// SalesStartAfter The ID of another ticket class - when it sells out, this class will go on sale.
		SalesStartAfter string `json:"sales_start_after"`

		// SecondaryAssignmentEnabled Has secondary barcode assignment enabled (for ex/ RFID)
		SecondaryAssignmentEnabled *bool `json:"secondary_assignment_enabled,omitempty"`

		// Sorting Unsigned number in the order ticket classes are sorted by.
		Sorting float32 `json:"sorting"`

		// SplitFee Absorb the payment fee, but show the eventbrite fee
		SplitFee bool `json:"split_fee"`
	} `json:"ticket_class,omitempty"`
}

