// RemainingBalance Remaining Balance
//
// Given an organization id and an event id returns an event-level balance specific to the time the endpoint is called.
//
// Corresponds with GET /balance/{public_organization_id}/events/{public_event_id}/ (the `RemainingBalance` operationId).
func (c *Client) RemainingBalance(ctx context.Context, publicOrganizationId string, publicEventId string, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewRemainingBalanceRequest(c.Server, publicOrganizationId, publicEventId)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

